import json,socket,ipaddress
host="serveriptv.duckdns.org"
vps="146.59.145.3"
out={"host":host}
try:
    resolved=set(x[4][0] for x in socket.getaddrinfo(host,None,proto=socket.IPPROTO_TCP))
    out["resolved_ipv4_count"]=sum(1 for ip in resolved if ipaddress.ip_address(ip).version==4)
    out["points_to_ferrari_vps"]=vps in resolved
    out["all_global"]=bool(resolved) and all(ipaddress.ip_address(ip).is_global for ip in resolved)
except OSError as exc:
    out["dns_error_type"]=type(exc).__name__
for port in [80,443,8096]:
    try:
        with socket.create_connection((host,port),timeout=2): out["target_tcp_"+str(port)]="open"
    except OSError as exc: out["target_tcp_"+str(port)]="unreachable:"+type(exc).__name__
print(json.dumps(out,sort_keys=True))
